#!/bin/bash
# Generated by dsh-super-injector dev_scaffold_plugin.
# Build: compile src/ → lib/ with the dsh checkout's tsc.
# Requires DSH_CHECKOUT pointing at a dsh source checkout (auto-probe below).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

# DSH_CHECKOUT 探测：环境变量 → 常见路径（home 下 dsh-harness）
CHECKOUT="${DSH_CHECKOUT:-}"
if [ -z "$CHECKOUT" ]; then
  for candidate in "$HOME/dsh-harness" "$HOME/dsh" "$HOME/.dsh/dsh-harness" "$HOME/deepseek-harness"; do
    if [ -d "$candidate/packages" ]; then CHECKOUT="$candidate"; break; fi
  done
fi
if [ -z "$CHECKOUT" ] || [ ! -d "$CHECKOUT/packages" ]; then
  echo "build: cannot locate the dsh checkout (set DSH_CHECKOUT)" >&2
  exit 1
fi

TSC="$CHECKOUT/node_modules/.bin/tsc"
if [ ! -x "$TSC" ] && [ ! -f "$TSC.cmd" ]; then
  echo "build: tsc not found at $TSC" >&2
  exit 1
fi

link_pkg() {
  local target="$CHECKOUT/$2"
  if [ ! -e "$target" ]; then
    echo "build: dependency target missing: $target" >&2
    exit 1
  fi
  node -e "
    const fs = require('fs');
    const path = require('path');
    const link = path.resolve(process.argv[1]);
    const target = path.resolve(process.argv[2]);
    fs.rmSync(link, { recursive: true, force: true });
    fs.mkdirSync(path.dirname(link), { recursive: true });
    fs.symlinkSync(target, link, process.platform === 'win32' ? 'junction' : 'dir');
  " "node_modules/$1" "$target"
}

echo "=== Linking build dependencies (checkout: $CHECKOUT) ==="
mkdir -p node_modules/@deepseek-ai
node -e "const fs=require('fs');fs.rmSync('node_modules/@standard-schema',{recursive:true,force:true})"
link_pkg cordis vendor/cordis
# vendor/cordis 的真实包名是 @deepseek-ai/cordis：socket 增强（declare module '@deepseek-ai/cordis'）
# 是按带 scope 的名字写的，所以两个名字都要在
link_pkg @deepseek-ai/cordis vendor/cordis
link_pkg cosmokit vendor/cosmokit
link_pkg schemastery vendor/schemastery
link_pkg @deepseek-ai/dsh-tools packages/core/tools
link_pkg @deepseek-ai/dsh-llm packages/llm/llm
link_pkg @deepseek-ai/dsh-system-prompt packages/core/system-prompt
# 客户端半的类型：ctx.slots 的声明在 ui-renderer/client 里（它 declare module '@deepseek-ai/cordis'），
# 而 SlotRegistry 等类型来自 ui-slots，两个都要链
link_pkg @deepseek-ai/dsh-client-ui-slots packages/client/ui-slots
link_pkg @deepseek-ai/dsh-client-ui-renderer packages/client/ui-renderer
# 用到的槽位键（main / sidebar.*）的 SlotMap 声明在这两个包里，官方客户端插件同样要 import
link_pkg @deepseek-ai/dsh-client-ui-layout packages/client/ui-layout
link_pkg @deepseek-ai/dsh-client-ui-sidebar packages/client/ui-sidebar
# @types/node（编译类型；checkout 自带）
link_pkg @types/node node_modules/@types/node

# @types/react（客户端半的类型检查需要它）。checkout 的 .pnpm 里用的是 @types+react@x.y.z 这种
# 扁平名，不能走 link_pkg 直链，照下面 @standard-schema 的先例用 find 定位再链。
TYPES_REACT=$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 1 -type d -iname '@types+react@*' 2>/dev/null | head -1)
if [ -z "$TYPES_REACT" ]; then
  echo "build: 找不到 @types/react —— 客户端半的类型检查需要它（checkout 里没有？）" >&2
  exit 1
fi
link_pkg @types/react "${TYPES_REACT#$CHECKOUT/}/node_modules/@types/react"

# 本插件自己的运行时依赖：从 checkout 的 .pnpm 里按包名取（不联网安装）
link_pnpm() {
  local dest="$1" pattern="$2" found
  found=$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 1 -type d -name "$pattern@*" 2>/dev/null | head -1)
  if [ -z "$found" ]; then
    echo "build: 找不到 pnpm 包 $pattern（checkout 里没有？）" >&2
    exit 1
  fi
  link_pkg "$dest" "${found#$CHECKOUT/}/node_modules/$dest"
}

link_pnpm fast-xml-parser fast-xml-parser
link_pnpm zod zod
# 自持存储的路径解析（resolveDshHome）：$DSH_HOME 的优先级语义（空白视为未设置）只有官方实现里
# 有，src/storage/paths.ts 曾手抄过一份，在 DSH_HOME 为纯空白时会把数据落到 CWD 上（Task 7 已删）
link_pkg @deepseek-ai/dsh-home-paths packages/util/home-paths
# ⚠️ 存储域这条 link **不再**服务于装载路径（Task 8 起插件一次也不 open 存储域），
# 但**还不能删**：src/domain.ts 里那行 import { defineDomain, domainTable }（定义 readerDomain 的）是**运行期**
# import，src/store.ts 里那行 import type { Domain } 是类型 import。删了这条，从零 build 直接 TS2307 ×2
# （实测，隔离副本里验过）。**这里刻意不写行号**：本文件的注释会随上面每次编辑漂移，
# 而「死行号」正是本轮在 paths.ts:5 与本行同时修掉的那类错误（源码核对：符号名不会漂）。
# 唯一的消费者是旧适配器 src/store.ts 的 createStore —— 它只被测试当
# 「旧实现 ↔ 自持实现」的同义性基线驱动（tests/overview-paging.test.mjs，且是变异门槛
# scripts/mutation-test.mjs:691 的判据）。等那套基线撤掉，这里和 package.json 的
# peerDependency 才能一起删。
link_pkg @deepseek-ai/dsh-storage-domain packages/storage/storage-domain
link_pkg @deepseek-ai/dsh-client-connection packages/client/connection
link_pkg @deepseek-ai/dsh-host-webserver packages/host/webserver

STD_SCHEMA=$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 1 -type d -iname '@standard-schema+spec@*' 2>/dev/null | head -1)
if [ -n "$STD_SCHEMA" ]; then
  node -e "
    const fs = require('fs');
    const path = require('path');
    fs.rmSync('node_modules/@standard-schema', { recursive: true, force: true });
    fs.mkdirSync('node_modules/@standard-schema', { recursive: true });
    fs.symlinkSync(path.resolve(process.argv[1]), path.resolve('node_modules/@standard-schema/spec'), process.platform === 'win32' ? 'junction' : 'dir');
  " "$STD_SCHEMA/node_modules/@standard-schema/spec"
fi

echo "=== Compiling src → lib ==="
"$TSC" -p tsconfig.json
# ── 客户端半：类型检查 + 声明产出 ──
# 这条原先是个启发式闸门（--noResolve 只把 TS2304/2551/2552 当致命，因为当时没有 react 类型）。
# 2026-10-07 起 tsconfig.client.json 能真正解析客户端半，所以换成真检查；同时补上 package.json
# 里 exports["./client"].types 指向的声明文件——那个路径原先悬空，没有任何构建步骤会产出它。
"$TSC" -p tsconfig.client.json --noEmit false --emitDeclarationOnly --declaration --outDir lib/types
echo "=== Build complete ==="